47: /// Handler for `GET /api/v1/flight/info`.
48: pub async fn get_flight_info(
49:     State(state): State<AppState>,
50: ) -> Result<Json<FlightInfoResponse>, ServerError> {
51:     let lock = state.dataset.read().await;
52: 
53:     match &*lock {
54:         Some(dataset) => {
55:             let mut min_lat = 90.0f64;
56:             let mut max_lat = -90.0f64;
57:             let mut min_lon = 180.0f64;
58:             let mut max_lon = -180.0f64;
59:             let mut min_alt = f64::INFINITY;
60:             let mut max_alt = f64::NEG_INFINITY;
61:             let mut valid_coords = 0usize;
62: 
63:             for pt in &dataset.points {
64:                 if pt.latitude != 0.0 || pt.longitude != 0.0 {
65:                     valid_coords += 1;
66:                     min_lat = min_lat.min(pt.latitude);
67:                     max_lat = max_lat.max(pt.latitude);
68:                     min_lon = min_lon.min(pt.longitude);
69:                     max_lon = max_lon.max(pt.longitude);
70:                     min_alt = min_alt.min(pt.altitude_msl);
71:                     max_alt = max_alt.max(pt.altitude_msl);
72:                 }
73:             }
74: 
75:             let bounds = if valid_coords > 0 {
76:                 Some(FlightBounds {
77:                     min_latitude: min_lat,
78:                     max_latitude: max_lat,
79:                     min_longitude: min_lon,
80:                     max_longitude: max_lon,
81:                     min_altitude_msl: min_alt,
82:                     max_altitude_msl: max_alt,
83:                 })
84:             } else {
85:                 None
86:             };
87: 
88:             Ok(Json(FlightInfoResponse {
89:                 loaded: true,
90:                 metadata: dataset.metadata.clone(),
91:                 events: Some(dataset.events.clone()),
92:                 bounds,
93:             }))
94:         }
95:         None => {
96:             let default_meta = FlightMetadata {
97:                 log_type: "NONE".to_string(),
